// th18_s3_w07 -- TH18 v1.00a Stage 3 wave.
// Source: st03.ecl.txt:1213-1242 (MainSub06/MainSub06b spawn schedule),
//         st03.ecl.txt:483-533 (GirlB02 main + GirlB02_at).
// Shell: invulnerable controller at (0,0), body collision off; 120-frame opening
// buffer before the wave starts. Real GirlB02 keep the source hit/hurt boxes and
// the source spawn coordinates (-216 / +216, y=128+RANDF2*32).
const TIME_LIMIT: int = 1900;
const TH18_BALL2: int = 432;   // TH18 type5 Ball2, base radius 4
const BALL2_COLOR: int = 10;   // source etSprite(0, 5, 10)

// Source bullet EX chain (GirlB02_at:0518-0521), in append order:
//   rec0 ANIM async=0, a=1  -> birth position -= 4*velocity (kept via sh_dist)
//   rec1 SPEEDUP async=1    -> bullet animation speed, pure visual, omitted
//   rec2 WAIT 60            -> cursor waits, motion continues
//   rec3 ACCEL a=60, r=1/60, s=sentinel -> constant 1/60 acceleration along the
//        current bullet angle for 60 frames, then the handler clears the vector.
// The ACCEL vector is parallel to the bullet's own velocity, so the tangential
// set_accel (speed += 1/60 per frame) is the same straight-line speed ramp.
xformdef B2_ACCEL {
    @60 add_speed(0fx); // WAIT 60 (op then post-delay)
    @60 set_accel(1fx / 60fx);
    set_accel(0fx); // ACCEL end, 60 frames after it started
}

// One volley. Source etAim(0,2) = player-aimed full ring, one A per volley;
// first volley alpha=0 delta=8deg, later volleys alpha=%RANDRAD delta=0.
// etCountD/etSpeedD resolve as [E,N,H,L] for both fields: E/N/H are one layer at
// 0.5 speed (5/11/17 ways); Lunatic is two layers (16 ways) at 0.5 and 1.0.
sub volley(rank: int, alpha: angle, layer_rot: angle) {
    if rank == 3 {
        // layer 0: speed 0.5, ANIM retreat 4*0.5
        sh_count(0, 16, 1);
        sh_speed(0, 0.5fx, 0fx);
        sh_dist(0, -2fx);
        sh_angle(0, alpha, 0deg);
        sh_fire(0);
        // layer 1: speed 1.0, ANIM retreat 4*1.0, extra q*delta rotation
        sh_speed(0, 1.0fx, 0fx);
        sh_dist(0, -4fx);
        sh_angle(0, alpha + layer_rot, 0deg);
        sh_fire(0);
    } else {
        var n: int = 11; // Normal
        if rank == 0 { n = 5; }
        if rank == 2 { n = 17; }
        sh_count(0, n, 1);
        sh_speed(0, 0.5fx, 0fx);
        sh_dist(0, -2fx);
        sh_angle(0, alpha, 0deg);
        sh_fire(0);
    }
}

async sub girl_fire() {
    var rank: int = global(GVAR_RANK);
    sh_reset(0);
    sh_sprite(0, TH18_BALL2, BALL2_COLOR);
    sh_ring(0, 1);
    sh_aim(0, 1);
    sh_xform(0, B2_ACCEL);
    volley(rank, 0deg, 8deg); // first etOn, alpha 0 / delta 8deg
    for k in 0..5 {
        wait(30 + rand(30)); // source wait(30 + $RAND % 30)
        volley(rank, rand(65536) as angle, 0deg); // etAngle(%RANDRAD, 0)
    }
}

// GirlB02 main. Source moveVel(-0.19634955,3), then +10 moveVelTime(120,1,0,0.3),
// then +150 moveVelTime(180,1,1.9634954,2.0), wait(60), idle loop.
// The right-side girl was created by enmCreateM (mirror=1), so its x velocity is
// negated: angle -> 180deg - angle.
async sub girl_main(side: int) {
    set_invuln(65535); // invulnerable practice shell
    set_hitbox(8fx);   // source setHitbox(16,16): native circle uses width*0.5
    set_hurtbox(14fx); // source setHurtbox(28,28)
    spawn girl_fire();
    if side == 0 {
        move_vel(0, -11.25deg, 3fx, EASE_LINEAR);
        wait(9); // source t=10, sub first runs one frame after creation
        move_vel(120, 0deg, 0.3fx, EASE_QUAD_IN);
        wait(140); // source t=150
        move_vel(180, 112.5deg, 2fx, EASE_QUAD_IN);
    } else {
        move_vel(0, 191.25deg, 3fx, EASE_LINEAR);
        wait(9);
        move_vel(120, 180deg, 0.3fx, EASE_QUAD_IN);
        wait(140);
        move_vel(180, 67.5deg, 2fx, EASE_QUAD_IN);
    }
    wait(60); // source t=150..210 wait
    loop { wait(1000); }
}

sub spawn_girl(side: int) {
    // source y = _f(128) + RANDF2 * _f(32)
    var y: fx = 128fx + (rand(32768) as fx) / 1024fx;
    if side == 0 {
        _ = spawn_enemy(-216fx, y, 500, 0, 0, 0, girl_main(0));
    } else {
        _ = spawn_enemy(216fx, y, 500, 0, 0, 0, girl_main(1));
    }
}

// 10 iterations x two girls, 60 frames apart. Left side is MainSub06 (item 2
// then item 1), right side is MainSub06b (item 1 then item 2); the item values
// are drop types and are omitted. MainSub06b started one frame after MainSub06.
async sub girl_wave(side: int) {
    if side == 1 { wait(1); }
    for i in 0..10 {
        spawn_girl(side);
        wait(60);
        spawn_girl(side);
        wait(60);
    }
}

async sub wave() {
    wait(120); // opening buffer before activating this wave
    spawn girl_wave(0);
    spawn girl_wave(1);
    loop { wait(1); }
}

async sub controller() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1); // control enemy at (0,0): no body collision
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, controller);
    loop { wait(600); }
}
